package slhdsa

import "testing"

type nistSigGenTestVector struct {
	name    string
	par     *params
	sk      string
	pk      string
	msg     string
	ctx     string
	wantSig string
}

type nistSigVerTestVector struct {
	name      string
	par       *params
	pk        string
	msg       string
	ctx       string
	sig       string
	wantValid bool
}

