// NIST ACVP signature verification test vectors (external interface, pure
// signing). There is one test case per parameter set, and the ACVP test reasons
// (valid signature, modified message, modified R/SIGFORS/SIGHT, too large and
// too small signature) are assigned to the parameter sets in turn, so that every
// reason is covered and most reasons are covered by both a SHA2 and a SHAKE
// parameter set. Taken from
// https://github.com/usnistgov/ACVP-Server/blob/975de31eb83d87039ec88934fdc47d8c312b892d/gen-val/json-files/SLH-DSA-sigVer-FIPS205/internalProjection.json.
func nistSigVerTestVectors(t *testing.T) []nistSigVerTestVector {
	t.Helper()
	return []nistSigVerTestVector{
		{
			// valid signature and message - signature should verify successfully
			name:      "SLH-DSA-SHA2-128s/tcId=258",
			par:       SLH_DSA_SHA2_128s,
			pk:        "de0aab517be80912c6a588ddbed2748b1d0b597199ba4954054422ed5ee03015",
			msg:       "",
			ctx:       "",
			sig:       "",
			wantValid: true,
		},
		{
			// modified message
			name:      "SLH-DSA-SHAKE-128s/tcId=337",
			par:       SLH_DSA_SHAKE_128s,
			pk:        "45a7ce1d3193a285c5412cbe75799db9db4e728e1c4acfa22bd07ac0195b9401",
			msg:       "",
			ctx:       "",
			sig:       "",
			wantValid: false,
		},
		{
			// modified signature - R
			name:      "SLH-DSA-SHA2-128f/tcId=8",
			par:       SLH_DSA_SHA2_128f,
			pk:        "42af75278d3a74c239eac900b4c4554bbf3c0de3368301b80e23a53f901e00dc",
			msg:       "",
			ctx:       "",
			sig:       "",
			wantValid: false,
		},
		{
			// modified signature - SIGFORS
			name:      "SLH-DSA-SHAKE-128f/tcId=94",
			par:       SLH_DSA_SHAKE_128f,
			pk:        "01245fc4a73a1c8223948c547db8f6c0a58792a1d13955c5c54623513359d6f6",
			msg:       "",
			ctx:       "",
			sig:       "",
			wantValid: false,
		},
		{
			// modified signature - SIGHT
			name:      "SLH-DSA-SHA2-192s/tcId=282",
			par:       SLH_DSA_SHA2_192s,
			pk:        "4b2b14201dca6932132a56719962c19ab56f92bf540c89006d08dbafe587a539a490b83cb49203a2c277fd24260d7462",
			msg:       "",
			ctx:       "acd7672b48aeb965873eb2bf4faa05ea2bb30b1144a0a3dfaa26d962ba9a68dbde65b656806235f654ff92102a11b721726360c8da2fb2632de78e7da40d651a4fdcd007cc784e8b7ce540f604d1c738a37e6f20b4b7b8af6c83cfcfeeb1dc94f697e2f2495b9fe284158092",
			sig:       "",
			wantValid: false,
		},
		{
			// invalid signature - too large
			name:      "SLH-DSA-SHAKE-192s/tcId=365",
			par:       SLH_DSA_SHAKE_192s,
			pk:        "3bc8bad315eeb5196845e4c5ba4f0e1d9c720aee30cca7db65024f256ef685b12ff0a3892ea1b043513ccaf6847ee423",
			msg:       "",
			ctx:       "8135bea539b0e94c7a67",
			sig:       "",
			wantValid: false,
		},
		{
			// invalid signature - too small
			name:      "SLH-DSA-SHA2-192f/tcId=29",
			par:       SLH_DSA_SHA2_192f,
			pk:        "0e1f8f24a8973fcc731f63d52995cb4f80d198fc29a67e868c30fce9a0707d5a9f10f31aec2f6812c9ef3756371f7835",
			msg:       "",
			ctx:       "",
			sig:       "",
			wantValid: false,
		},
		{
			// valid signature and message - signature should verify successfully
			name:      "SLH-DSA-SHAKE-192f/tcId=113",
			par:       SLH_DSA_SHAKE_192f,
			pk:        "2dfaef867e813c3ba9e636b447fca7d02af615764bb9bae15cdafcd0f7748d334d0d842e69aeb8ed98c447437e604857",
			msg:       "",
			ctx:       "",
			sig:       "",
			wantValid: true,
		},
		{
			// modified message
			name:      "SLH-DSA-SHA2-256s/tcId=309",
			par:       SLH_DSA_SHA2_256s,
			pk:        "19d3f2bc2a605cf0f5178e1b1555f80b50f7cf9d2f3a11f17ae87eec5d3d4b11b2f3867d83372511586cbe74d137b3d20b79778bf278e1b0980639286d5d3574",
			msg:       "",
			ctx:       "fe915ad71a4c7bc2fcaef8832d7dc088de",
			sig:       "",
			wantValid: false,
		},
		{
			// modified signature - R
			name:      "SLH-DSA-SHAKE-256s/tcId=400",
			par:       SLH_DSA_SHAKE_256s,
			pk:        "d0a2d2b391d6b6c25b38608d8a88da132f2987a550bf800ad561d7ac5900affaa2f5826af91bfa67e7781d70a657d2f5d08ac95ca1e459db396384514bdcf0a3",
			msg:       "",
			ctx:       "56b674dafd3df641f72a1810fa594740fd8526eae5348d9f488c37d499a37258b9730b978cb284045e84b34a2ef90a9561aaee1a7c3676",
			sig:       "",
			wantValid: false,
		},
		{
			// modified signature - SIGFORS
			name:      "SLH-DSA-SHA2-256f/tcId=58",
			par:       SLH_DSA_SHA2_256f,
			pk:        "d7138f9e78a8a004bf098b1606386703b41ac13901654a314656ab3bc5bcca19fe7ac8b163b6fccd15fcd27c0abc88967a57d9fc6ddaf8eb1e6fe6db0473701a",
			msg:       "",
			ctx:       "a72c28b52432f22623b5af77d4743823a5c2693c86ada3453f6d3eab8b89b33d5ae2bfe761880955f803013771a1c56d5a08f5e339849b67138a3e2d88ea2a",
			sig:       "",
			wantValid: false,
		},
		{
			// modified signature - SIGHT
			name:      "SLH-DSA-SHAKE-256f/tcId=146",
			par:       SLH_DSA_SHAKE_256f,
			pk:        "ee836e998341b26497577a33ba6e63c0e85d7180d3f11f1a85d5f2c1009ecee031203dc1f7917f8e216c1c4be1ee0f53c946b39e81da275eb7afb6473b140288",
			msg:       "",
			ctx:       "",
			sig:       "",
			wantValid: false,
		},
	}
}
